	router.POST(options.BaseURL+"/auth/refresh", wrapper.RefreshToken, options.OperationMiddlewares["refreshToken"]...)
	router.GET(options.BaseURL+"/departments", wrapper.ListDepartments, options.OperationMiddlewares["listDepartments"]...)
	router.GET(options.BaseURL+"/departments/:departmentId", wrapper.GetDepartment, options.OperationMiddlewares["getDepartment"]...)
	router.GET(options.BaseURL+"/expense-claims", wrapper.ListExpenseClaims, options.OperationMiddlewares["listExpenseClaims"]...)
	router.POST(options.BaseURL+"/expense-claims", wrapper.CreateExpenseClaim, options.OperationMiddlewares["createExpenseClaim"]...)
	router.DELETE(options.BaseURL+"/expense-claims/:claimId", wrapper.DeleteExpenseClaim, options.OperationMiddlewares["deleteExpenseClaim"]...)
	router.GET(options.BaseURL+"/expense-claims/:claimId", wrapper.GetExpenseClaim, options.OperationMiddlewares["getExpenseClaim"]...)
	router.PATCH(options.BaseURL+"/expense-claims/:claimId", wrapper.UpdateExpenseClaim, options.OperationMiddlewares["updateExpenseClaim"]...)
	router.POST(options.BaseURL+"/expense-claims/:claimId/accounting-approve", wrapper.AccountingApproveExpenseClaim, options.OperationMiddlewares["accountingApproveExpenseClaim"]...)
	router.POST(options.BaseURL+"/expense-claims/:claimId/attachments", wrapper.UploadAttachment, options.OperationMiddlewares["uploadAttachment"]...)
