	router.GET(options.BaseURL+"/expense-claims/:claimId/attachments/:attachmentId/download", wrapper.DownloadAttachment, options.OperationMiddlewares["downloadAttachment"]...)
	router.POST(options.BaseURL+"/expense-claims/:claimId/cancel", wrapper.CancelExpenseClaim, options.OperationMiddlewares["cancelExpenseClaim"]...)
	router.POST(options.BaseURL+"/expense-claims/:claimId/manager-approve", wrapper.ManagerApproveExpenseClaim, options.OperationMiddlewares["managerApproveExpenseClaim"]...)
